<?php
defined('ABSPATH')||exit;
final class AIM_Wallet_Bridge {
 static function artifact(){return json_decode(file_get_contents(__DIR__.'/contracts/AIMTradingVault.json'),true);}
 static function rpc($method,$args){if(!function_exists('aim_chain_rpc'))throw new RuntimeException('Cần bật AIM Wallet.');$r=aim_chain_rpc($method,$args);if(is_wp_error($r))throw new RuntimeException($r->get_error_message());return $r;}
 static function address($v){if(!is_string($v)||!preg_match('/^0x[0-9a-fA-F]{40}$/D',$v))throw new RuntimeException('Địa chỉ ví không hợp lệ.');return strtolower($v);}
 static function wallet($uid){$w=get_user_meta($uid,'_aim_privy_wallet',true);if((int)($w['chain_id']??0)!==84532)throw new RuntimeException('Liên kết ví Base Sepolia trong mục Tài khoản trước.');return self::address($w['address']??'');}
 static function units($value){if(!is_string($value)||!preg_match('/^(0|[1-9][0-9]{0,9})(?:\.([0-9]{1,6}))?$/D',$value,$m))throw new RuntimeException('Số AIM tối đa 6 chữ số thập phân.');$n=(int)$m[1]*1000000+(int)str_pad($m[2]??'',6,'0');if($n<=0||$n>1000000000000000)throw new RuntimeException('Số AIM phải từ 0,000001 đến 1 tỷ.');return $n;}
 static function decimal_hex($hex){if(!function_exists('bcadd'))throw new RuntimeException('Máy chủ cần BCMath.');if(!preg_match('/^0x[0-9a-fA-F]{64}$/D',$hex))throw new RuntimeException('Số liệu blockchain không hợp lệ.');$n='0';foreach(str_split(substr($hex,2)) as $digit)$n=bcadd(bcmul($n,'16',0),(string)hexdec($digit),0);if(bcmod($n,'1000000000000')!=='0')throw new RuntimeException('Giao dịch vượt độ chính xác 6 chữ số của app.');$micro=bcdiv($n,'1000000000000',0);if(bccomp($micro,'1000000000000000')>0||bccomp($micro,'0')<=0)throw new RuntimeException('Số AIM nằm ngoài giới hạn.');return (int)$micro;}
 static function config(){ $c=get_option('aimtr_vault_v1');if(!$c)throw new RuntimeException('Chủ ví chưa triển khai và kết nối kho AIM.');if(strtolower(get_option('aim_chain_contract_v1')['address']??'')!==$c['token'])throw new RuntimeException('Hợp đồng AIM đã thay đổi; tạm dừng cầu nối để đối soát.');return $c;}
 static function migrate(){if(!current_user_can('manage_options')||get_option('aimtr_bridge_schema')==='1')return;global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$t=AIM_Trading::table('bridge');$collate=$wpdb->get_charset_collate();dbDelta("CREATE TABLE $t (id bigint(20) unsigned NOT NULL AUTO_INCREMENT, user_id bigint(20) unsigned NOT NULL, request_id varchar(66) NOT NULL, direction varchar(12) NOT NULL, amount bigint(20) NOT NULL, address varchar(42) NOT NULL, status varchar(16) NOT NULL, tx varchar(66) DEFAULT NULL, created datetime NOT NULL, PRIMARY KEY  (id), UNIQUE KEY request_once (request_id), UNIQUE KEY tx_once (tx), KEY member (user_id)) ENGINE=InnoDB $collate;");$engine=$wpdb->get_var($wpdb->prepare('SELECT ENGINE FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=%s',$t));if(strtoupper((string)$engine)==='INNODB')update_option('aimtr_bridge_schema','1',false);}
 static function receipt($hash){if(!is_string($hash)||!preg_match('/^0x[0-9a-fA-F]{64}$/D',$hash))throw new RuntimeException('Nhập đúng mã giao dịch 0x…');if(hexdec(self::rpc('eth_chainId',array()))!==84532)throw new RuntimeException('Sai mạng Base Sepolia.');$r=self::rpc('eth_getTransactionReceipt',array(strtolower($hash)));if(!$r||($r['status']??'')!=='0x1')throw new RuntimeException('Giao dịch chưa thành công.');$head=hexdec(self::rpc('eth_blockNumber',array()));if($head<hexdec($r['blockNumber'])+11)throw new RuntimeException('Đợi đủ 12 xác nhận rồi kiểm tra lại.');$b=self::rpc('eth_getBlockByNumber',array($r['blockNumber'],false));if(!$b||strtolower($b['hash']??'')!==strtolower($r['blockHash']??''))throw new RuntimeException('Khối chưa ổn định.');return $r;}
 static function register($p){$record=get_option('aim_chain_contract_v1');if(!$record||(int)$record['chainId']!==84532)throw new RuntimeException('Chưa có AIM testnet.');$owner=self::wallet(get_current_user_id());if($owner!==strtolower($record['owner']))throw new RuntimeException('Cần ví chủ AIM.');$r=self::receipt($p['tx']??'');$address=self::address($r['contractAddress']??'');if(strtolower($r['from'])!==$owner)throw new RuntimeException('Sai ví triển khai.');$artifact=self::artifact();if(strtolower(self::rpc('eth_getCode',array($address,'latest')))!==strtolower($artifact['runtime']))throw new RuntimeException('Mã hợp đồng không khớp bản kiểm tra.');foreach(array('owner'=>$owner,'token'=>strtolower($record['address'])) as $field=>$value){$got=self::rpc('eth_call',array(array('to'=>$address,'data'=>$artifact['selectors'][$field]),'latest'));if(strtolower('0x'.substr($got,-40))!==$value)throw new RuntimeException('Hợp đồng sai '.$field);}$c=array('address'=>$address,'owner'=>$owner,'token'=>strtolower($record['address']),'chain_id'=>84532,'deployment_tx'=>strtolower($p['tx']));$old=get_option('aimtr_vault_v1');if($old&&$old['address']!==$address)throw new RuntimeException('Đã có kho AIM, không thay kho đang dùng.');if(!$old&&!add_option('aimtr_vault_v1',$c,'',false))throw new RuntimeException('Chưa lưu kho, kiểm tra lại giao dịch.');return array('vault'=>$old?:$c);}
 static function snapshot(){global $wpdb;$uid=get_current_user_id();$c=get_option('aimtr_vault_v1',null);$t=AIM_Trading::table('bridge');$items=get_option('aimtr_bridge_schema')==='1'?$wpdb->get_results($wpdb->prepare("SELECT * FROM $t WHERE user_id=%d ORDER BY id DESC LIMIT 30",$uid),ARRAY_A):array();return array('vault'=>$c,'wallet'=>(get_user_meta($uid,'_aim_privy_wallet',true)['address']??''),'account'=>AIM_Trading::account(),'auto_deposit'=>class_exists('AIM_Wallet_Automation')?AIM_Wallet_Automation::auto_deposit_state($uid):'off','wallet_first'=>class_exists('AIM_Wallet_Automation')&&AIM_Wallet_Automation::wallet_first($uid),'automatic_payouts'=>class_exists('AIM_Wallet_Automation')&&AIM_Wallet_Automation::enabled(),'items'=>$items,'queue'=>current_user_can('manage_options')&&$c?$wpdb->get_results("SELECT * FROM $t WHERE direction='withdraw' AND status='pending' ORDER BY id LIMIT 50",ARRAY_A):array());}
 static function transfer_log($r,$c,$type,$address,$id=null){$artifact=self::artifact();$matches=array();foreach($r['logs']??array() as $log){if(strtolower($log['address']??'')!==$c['address']||strtolower($log['topics'][0]??'')!==$artifact['selectors'][$type])continue;$topics=$log['topics'];if(count($topics)!==($type==='deposit'?2:3))continue;$who=strtolower('0x'.substr($topics[$type==='deposit'?1:2],-40));if($who!==$address)continue;if($id&&strtolower($topics[1])!==$id)continue;$matches[]=self::decimal_hex($log['data']);}if(count($matches)!==1)throw new RuntimeException('Không tìm thấy đúng một sự kiện nạp/rút của ví này.');return $matches[0];}
 static function mutate($request){$p=$request->get_json_params();try{if(!is_array($p))throw new RuntimeException('Yêu cầu không hợp lệ.');$type=$p['type']??'';if($type==='auto-welcome')return AIM_Wallet_Automation::auto_deposit_claim($p);if(in_array($type,array('deposit','withdraw'),true)&&class_exists('AIM_Wallet_Automation')&&AIM_Wallet_Automation::wallet_first(get_current_user_id())){$init=AIM_Trading::init_account(get_current_user_id());if(is_wp_error($init))return $init;}if($type==='register'){if(!current_user_can('manage_options'))return AIM_Trading::error('Chỉ quản trị kết nối kho.',403);return self::register($p);}if(get_option('aimtr_bridge_schema')!=='1')throw new RuntimeException('Quản trị cần mở bảng điều khiển để cập nhật dữ liệu.');$c=self::config();$uid=get_current_user_id();$address=self::wallet($uid);$hash=null;$n=0;$id=null;
 if($type==='deposit'){$hash=strtolower($p['tx']??'');$r=self::receipt($hash);/* Sponsored AA transactions have bundler/EntryPoint outer addresses. The verified vault's Deposited event binds the actual member and escrowed amount. */$n=self::transfer_log($r,$c,'deposit',$address);$id='dep-'.substr(hash('sha256',$hash),0,56);}
 elseif($type==='withdraw'){$n=self::units($p['amount']??'');if(!is_string($p['request_id']??null)||!preg_match('/^[a-zA-Z0-9-]{16,50}$/D',$p['request_id']))throw new RuntimeException('Mã yêu cầu không hợp lệ.');$id='0x'.hash('sha256',$c['address'].':'.$uid.':'.$p['request_id']);}
 elseif($type==='confirm'){if(!current_user_can('manage_options'))return AIM_Trading::error('Chỉ quản trị xác nhận trả AIM.',403);$id=$p['id']??'';if(!is_string($id)||!preg_match('/^0x[0-9a-f]{64}$/D',$id))throw new RuntimeException('Mã rút không hợp lệ.');$hash=strtolower($p['tx']??'');$r=self::receipt($hash);if(strtolower($r['to']??'')!==$c['address'])throw new RuntimeException('Sai kho thanh toán.');}
 else throw new RuntimeException('Thao tác không hợp lệ.');
 global $wpdb;$a=AIM_Trading::table('accounts');$l=AIM_Trading::table('ledger');$t=AIM_Trading::table('bridge');if($wpdb->query('START TRANSACTION')===false)throw new RuntimeException('Chưa khóa dữ liệu.');try{
 $pool=$wpdb->get_row("SELECT * FROM $a WHERE user_id=0 FOR UPDATE",ARRAY_A);if(!$pool||$wpdb->last_error)throw new RuntimeException('Chưa khóa được quỹ.');
 $prior=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE request_id=%s FOR UPDATE",$id),ARRAY_A);if($wpdb->last_error)throw new RuntimeException('Chưa đọc được lịch sử.');
 if($type==='confirm'){if(!$prior||$prior['direction']!=='withdraw')throw new RuntimeException('Không có yêu cầu rút.');$n=self::transfer_log($r,$c,'paid',$prior['address'],$id);if($n!==(int)$prior['amount'])throw new RuntimeException('Số trả không khớp.');if($prior['status']==='paid'){if($prior['tx']!==$hash)throw new RuntimeException('Giao dịch khác.');$wpdb->query('ROLLBACK');return array('replayed'=>true);}if($wpdb->update($t,array('status'=>'paid','tx'=>$hash),array('id'=>$prior['id']))===false)throw new RuntimeException('Chưa lưu xác nhận.');}
 else{
 if($prior){if((int)$prior['user_id']!==$uid||(int)$prior['amount']!==$n)throw new RuntimeException('Mã yêu cầu đã dùng.');$wpdb->query('ROLLBACK');return array('replayed'=>true);}
 $wallet=$wpdb->get_row($wpdb->prepare("SELECT * FROM $a WHERE user_id=%d FOR UPDATE",$uid),ARRAY_A);if(!$wallet||$wpdb->last_error)throw new RuntimeException('Nhận vốn khởi đầu trong app trước.');
 if($type==='withdraw'){$res=AIM_Limit_Orders::reserved($uid);if(is_wp_error($res))throw new RuntimeException('Chưa kiểm tra được lệnh giữ vốn.');if((int)$wallet['cash']-(int)$res['cash']<$n)throw new RuntimeException('AIM khả dụng không đủ. Đóng vị thế/chuyển từ Phái sinh về trước.');}
 if($type==='deposit'&&(int)$wallet['cash']>9000000000000000-$n)throw new RuntimeException('Số dư vượt giới hạn app.');$delta=$type==='deposit'?$n:-$n;$date=current_time('mysql',true);
 if($wpdb->query($wpdb->prepare("UPDATE $a SET cash=cash+(%d),updated=%s WHERE user_id=%d",$delta,$date,$uid))===false)throw new RuntimeException('Chưa ghi số dư.');
 if($wpdb->insert($t,array('user_id'=>$uid,'request_id'=>$id,'direction'=>$type,'amount'=>$n,'address'=>$address,'status'=>$type==='deposit'?'credited':'pending','tx'=>$hash,'created'=>$date))===false)throw new RuntimeException('Giao dịch đã dùng hoặc chưa ghi được lịch sử.');
 if($wpdb->insert($l,array('user_id'=>$uid,'request_id'=>'bridge-'.substr(hash('sha256',$id),0,50),'kind'=>$type==='deposit'?'wallet_deposit':'wallet_withdraw','cash_delta'=>$delta,'pool_delta'=>0,'cash_after'=>(int)$wallet['cash']+$delta,'created'=>$date))===false)throw new RuntimeException('Chưa ghi được sổ AIM.');
 }
 if($wpdb->query('COMMIT')===false)return AIM_Trading::error('Chưa rõ kết quả. Kiểm tra lịch sử rồi thử lại đúng yêu cầu.',503);return array('ok'=>true);
 }catch(Throwable $x){$wpdb->query('ROLLBACK');throw $x;}
 }catch(Throwable $x){return AIM_Trading::error($x->getMessage(),409);}}
 static function routes(){register_rest_route('aim-trading/v1','/wallet',array('methods'=>'GET','permission_callback'=>array('AIM_Trading','permission'),'callback'=>array(__CLASS__,'snapshot')));register_rest_route('aim-trading/v1','/wallet-action',array('methods'=>'POST','permission_callback'=>array('AIM_Trading','permission'),'callback'=>array(__CLASS__,'mutate')));}
}
add_action('admin_init',array('AIM_Wallet_Bridge','migrate'),25);
add_action('rest_api_init',array('AIM_Wallet_Bridge','routes'));
